dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "tissue",
      "label": "Tissue*",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/keys/diff-exp/2?columns=tissue",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "gene",
      "label": "Gene",
      "type": "input"
    }
  ],
  "tab groups": [
    {
      "label": "Gene expression gene x tissue",
      "group id": "gene_diff_exp",
      "sections": [
        {
          "section": "diff_exp",
          "label": "Expression of the selected gene across strain or sex in the selected tissue"
        }
      ]
    },
    {
      "label": "Gene expression summary",
      "group id": "gene_diff_exp_summary",
      "sections": [
        {
          "section": "diff_exp_summary",
          "label": "Differential gene expression in the selected tissue"
        },
        {
          "section": "diff_exp_summary_gene",
          "label": "Differential gene expression across tissues"
        }
      ]
    },
    {
      "label": "Gene associations",
      "group id": "human_gene_asso",
      "sections": [
        {
          "section": "huge",
          "label": "Human Genetic Evidence Calculator scores"
        },
        {
          "section": "common_variant",
          "label": "Common variant associations"
        },
        {
          "section": "rare_variant",
          "label": "Rare variant associations"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "diff_exp_summary",
      "header": "Most expressed genes in a tissue (P-value <= 0.05)",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/diff-exp-summary-tissue?q=$tissue",
        "continue url": "https://bioindex-dev.hugeamp.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "tissue"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "filters": [
        {
          "field": "Gene",
          "label": "Gene",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "Chromosome",
          "label": "Chromosome",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Adjusted p-value: sex",
          "label": "Adjusted p-value: sex (&le;)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Adjusted p-value: strain",
          "label": "Adjusted p-value: strain (&le;)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Adjusted p-value: strain + sex",
          "label": "Adjusted p-value: strain + sex (&le;)",
          "type": "search lower than",
          "label in bubble": "true"
        }
      ],
      "table format": {
        "initial sort by": {
          "field": "Adjusted p-value: strain",
          "type": "number",
          "direction": "asc"
        },
        "data convert": [
          {
            "type": "join multi",
            "field name": "Gene region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Gene ID",
            "raw field": "gene_id"
          },
          {
            "type": "raw",
            "field name": "Adjusted p-value: sex",
            "raw field": "P_adj_sex"
          },
          {
            "type": "raw",
            "field name": "Adjusted p-value: strain",
            "raw field": "P_adj_strain"
          },
          {
            "type": "raw",
            "field name": "Adjusted p-value: strain + sex",
            "raw field": "P_adj_strain_sex"
          }
        ],
        "top rows": [
          "Gene",
          "Gene ID",
          "Gene region",
          "Adjusted p-value: sex",
          "Adjusted p-value: strain",
          "Adjusted p-value: strain + sex"
        ],
        "column formatting": {
          "Gene": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Search Gene",
                "parameter": [
                  "gene"
                ]
              }
            ]
          },
          "Adjusted p-value: sex": {
            "type": [
              "scientific notation"
            ],
            "percent if empty": 1
          },
          "Adjusted p-value: strain": {
            "type": [
              "scientific notation"
            ],
            "percent if empty": 1
          },
          "Adjusted p-value: strain + sex": {
            "type": [
              "scientific notation"
            ],
            "percent if empty": 1
          }
        }
      }
    },
    {
      "section id": "diff_exp_summary_gene",
      "header": "Gene expression across tissues",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/diff-exp-summary-gene?q=$gene",
        "continue url": "https://bioindex-dev.hugeamp.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Adjusted p-value: sex",
            "raw field": "P_adj_sex"
          },
          {
            "type": "raw",
            "field name": "Adjusted p-value: strain",
            "raw field": "P_adj_strain"
          },
          {
            "type": "raw",
            "field name": "Adjusted p-value: strain + sex",
            "raw field": "P_adj_strain_sex"
          }
        ],
        "top rows": [
          "Tissue",
          "Adjusted p-value: sex",
          "Adjusted p-value: strain",
          "Adjusted p-value: strain + sex"
        ],
        "column formatting": {
          "Tissue": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Search Tissue",
                "parameter": [
                  "tissue"
                ]
              }
            ]
          },
          "Adjusted p-value: sex": {
            "type": [
              "scientific notation"
            ],
            "percent if empty": 1
          },
          "Adjusted p-value: strain": {
            "type": [
              "scientific notation"
            ],
            "percent if empty": 1
          },
          "Adjusted p-value: strain + sex": {
            "type": [
              "scientific notation"
            ],
            "percent if empty": 1
          }
        }
      }
    },
    {
      "section id": "diff_exp",
      "header": "Gene expression on selected tissue by founders and sex",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/diff-exp?q=$gene,$tissue",
        "continue url": "https://bioindex-dev.hugeamp.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "gene",
          "tissue"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "filters": [
        {
          "field": "Founder",
          "label": "Founder",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Sex",
          "label": "Sex",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Founder",
            "raw field": "founder"
          },
          {
            "type": "raw",
            "field name": "Sex",
            "raw field": "sex"
          },
          {
            "type": "join multi",
            "field name": "Founder + sex",
            "fields to join": [
              "founder",
              "sex"
            ],
            "join by": [
              "_"
            ]
          },
          {
            "type": "raw",
            "field name": "Gene expression",
            "raw field": "expression"
          }
        ],
        "top rows": [
          "Founder + sex",
          "Founder",
          "Sex",
          "Gene expression"
        ],
        "column formatting": {
          "Gene expression": {
            "type": [
              "render background percent"
            ],
            "percent if empty": 0
          }
        }
      },
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "Gene expression by strain",
            "type": "phewas plot",
            "group by": "Founder",
            "y axis field": "Gene expression",
            "convert y -log10": "false",
            "y ticks decimal point": "2",
            "render by": "Founder + sex",
            "y axis label": "Gene expression",
            "x axis label": "Founder",
            "beta field": null,
            "hover content": [
              "Gene expression"
            ],
            "thresholds": [
              10
            ],
            "label in black": "greater than",
            "height": 300,
            "plot margin": {
              "top": 300,
              "bottom": 150,
              "left": 150,
              "right": 175
            }
          },
          {
            "label": "Gene expression by sex",
            "type": "phewas plot",
            "group by": "Sex",
            "y axis field": "Gene expression",
            "convert y -log10": "false",
            "y ticks decimal point": "2",
            "render by": "Founder + sex",
            "y axis label": "Gene expression",
            "x axis label": "Sex",
            "beta field": null,
            "hover content": [
              "Gene expression"
            ],
            "thresholds": [
              10
            ],
            "label in black": "greater than",
            "height": 300,
            "plot margin": {
              "top": 300,
              "bottom": 150,
              "left": 150,
              "right": 175
            }
          }
        ]
      }
    },
    {
      "section id": "huge",
      "header": "HuGE Scores: phenotype associations with corresponding human gene",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/huge?q=$gene",
        "continue url": "https://bioindex-dev.hugeamp.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "kp phenotype name",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "HuGE score",
            "raw field": "huge"
          },
          {
            "type": "js math",
            "field name": "HuGE log",
            "raw field": "huge",
            "method": "log"
          },
          {
            "type": "raw",
            "field name": "Common Variation Bayes Factor",
            "raw field": "bf_common"
          },
          {
            "type": "raw",
            "field name": "Rare Variation Bayes Factor",
            "raw field": "bf_rare"
          }
        ],
        "top rows": [
          "Phenotype",
          "HuGE score",
          "Common Variation Bayes Factor",
          "Rare Variation Bayes Factor"
        ],
        "column formatting": {
          "Phenotype": {
            "type": [
              "kp phenotype name"
            ]
          },
          "HuGE score": {
            "type": [
              "scientific notation",
              "render background percent"
            ],
            "percent if empty": 1
          },
          "Common Variation Bayes Factor": {
            "type": [
              "scientific notation",
              "render background percent"
            ],
            "percent if empty": 1
          },
          "Rare Variation Bayes Factor": {
            "type": [
              "scientific notation",
              "render background percent"
            ],
            "percent if empty": 1
          }
        }
      },
      "visualizer": {
        "type": "phewas plot",
        "group by": "phenotype group",
        "y axis field": "HuGE log",
        "convert y -log10": "false",
        "y ticks decimal point": "2",
        "phenotype map": "kp phenotype map",
        "render by": "phenotype",
        "y axis label": "Log(HuGE score)",
        "x axis label": "Phenotype",
        "beta field": "null",
        "hover content": [
          "HuGE score",
          "Common Variation Bayes Factor",
          "Rare Variation Bayes Factor"
        ],
        "label in black": "greater than",
        "thresholds": [
          "0.47712125472",
          "1.47712125472"
        ],
        "height": 400,
        "star key": "Phenotype",
        "plot margin": {
          "top": 300,
          "bottom": 250,
          "left": 150,
          "right": 175
        }
      }
    },
    {
      "section id": "common_variant",
      "header": "Common variant association: phenotype associations with corresponding human gene",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/gene-associations?q=$gene",
        "continue url": "https://bioindex-dev.hugeamp.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "kp phenotype name",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Variants",
            "raw field": "nParam"
          },
          {
            "type": "raw",
            "field name": "Z-Stat",
            "raw field": "zStat"
          },
          {
            "type": "raw",
            "field name": "Sample size",
            "raw field": "subjects"
          }
        ],
        "top rows": [
          "Phenotype",
          "P-value",
          "Variants",
          "Z-Stat",
          "Sample size"
        ],
        "column formatting": {
          "Phenotype": {
            "type": [
              "kp phenotype name"
            ]
          },
          "P-value": {
            "type": [
              "scientific notation",
              "render background percent"
            ],
            "percent if empty": 1
          },
          "Z-Stat": {
            "type": [
              "scientific notation",
              "render background percent"
            ],
            "percent if empty": 1
          }
        }
      },
      "visualizer": {
        "type": "phewas plot",
        "group by": "phenotype group",
        "y axis field": "-log10(P-Value)",
        "convert y -log10": "false",
        "y ticks decimal point": "2",
        "phenotype map": "kp phenotype map",
        "render by": "phenotype",
        "y axis label": "-Log10(P-Value)",
        "x axis label": "Phenotype",
        "beta field": "null",
        "hover content": [
          "P-value",
          "Variants",
          "Z-Stat",
          "Sample size"
        ],
        "label in black": "greater than",
        "thresholds": [
          "2.5e-6"
        ],
        "height": 400,
        "star key": "Phenotype",
        "plot margin": {
          "top": 300,
          "bottom": 250,
          "left": 150,
          "right": 175
        }
      }
    },
    {
      "section id": "rare_variant",
      "header": "Rare variant association: phenotype associations with corresponding human gene",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/query/gene-associations-52k?q=$gene",
        "continue url": "https://bioindex-dev.hugeamp.org/api/bio/cont?limit=20000&token=",
        "parameters": [
          "gene"
        ],
        "parameters type": "replace",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "kp phenotype name",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Odds Ratio",
            "raw field": "oddsRatio"
          }
        ],
        "top rows": [
          "Phenotype",
          "P-value",
          "Beta"
        ],
        "column formatting": {
          "Phenotype": {
            "type": [
              "kp phenotype name"
            ]
          },
          "P-value": {
            "type": [
              "scientific notation"
            ],
            "percent if empty": 1
          }
        }
      },
      "visualizer": {
        "type": "phewas plot",
        "group by": "phenotype group",
        "y axis field": "-log10(P-Value)",
        "convert y -log10": "false",
        "y ticks decimal point": "2",
        "phenotype map": "kp phenotype map",
        "render by": "phenotype",
        "y axis label": "-Log10(P-Value)",
        "x axis label": "Phenotype",
        "beta field": "Beta",
        "hover content": [
          "P-value",
          "Beta",
          "Odds Ratio"
        ],
        "label in black": "greater than",
        "thresholds": [
          "2.5e-6"
        ],
        "height": 400,
        "star key": "Phenotype",
        "plot margin": {
          "top": 300,
          "bottom": 250,
          "left": 150,
          "right": 175
        }
      }
    }
  ]
}
